import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.CRfKVJQk.js";const u=JSON.parse('{"title":"05 · Edge cases","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/05-edge-cases.md","filePath":"architecture/05-edge-cases.md"}'),r={name:"architecture/05-edge-cases.md"};function s(i,t,n,c,l,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="_05-·-edge-cases" tabindex="-1">05 · Edge cases <a class="header-anchor" href="#_05-·-edge-cases" aria-label="Permalink to &quot;05 · Edge cases&quot;">​</a></h1><p>Every known edge case, what the user sees, and where in the code it&#39;s handled. <strong>Status</strong>: ✅ handled · ⚠️ handled with a documented limitation · ⛔ not supported (documented).</p><h2 id="a-setup-and-installation" tabindex="-1">A. Setup and installation <a class="header-anchor" href="#a-setup-and-installation" aria-label="Permalink to &quot;A. Setup and installation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Case</th><th>What happens</th><th>Where</th><th>Status</th></tr></thead><tbody><tr><td>A1</td><td>Library installed but app not rebuilt</td><td>JS fallback (tinted view), one dev warning</td><td><code>nativeBridge.isNativeAvailable</code>, <code>LiquidGlassView.tsx</code></td><td>✅</td></tr><tr><td>A2</td><td>Expo Go</td><td>Same as A1. Works in Expo dev builds</td><td>same</td><td>✅</td></tr><tr><td>A3</td><td>Jest tests in the host app</td><td>Module is null → fallback renders, no crash</td><td>same</td><td>✅</td></tr><tr><td>A4</td><td>React Native Web</td><td><code>nativeBridge.web.ts</code> → CSS <code>backdrop-filter</code> glass</td><td><code>FallbackGlass.tsx</code></td><td>✅</td></tr><tr><td>A5</td><td>Old Architecture (bridge) app</td><td>Not supported</td><td>ADR-008</td><td>⛔</td></tr><tr><td>A6</td><td>Android minSdk &lt; 24 host app</td><td>Gradle refuses (RN itself needs 24)</td><td><code>android/gradle.properties</code></td><td>✅</td></tr><tr><td>A7</td><td>iOS built with Xcode &lt; 26</td><td>Compiles; uses materials instead of <code>UIGlassEffect</code></td><td><code>LG_HAS_GLASS_SDK</code> guard</td><td>✅</td></tr></tbody></table><h2 id="b-props-and-values" tabindex="-1">B. Props and values <a class="header-anchor" href="#b-props-and-values" aria-label="Permalink to &quot;B. Props and values&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Case</th><th>What happens</th><th>Where</th><th>Status</th></tr></thead><tbody><tr><td>B1</td><td>Unknown <code>material</code></td><td>Falls back to theme default, warns once</td><td><code>resolveMaterial</code></td><td>✅</td></tr><tr><td>B2</td><td>Unknown <code>quality</code></td><td><code>auto</code>, warns once</td><td><code>normalizeQuality</code></td><td>✅</td></tr><tr><td>B3</td><td>NaN / Infinity / negative numbers</td><td>Replaced by the material default or clamped</td><td><code>clamp</code>, <code>GlassConfig.sanitized</code></td><td>✅</td></tr><tr><td>B4</td><td><code>blur</code> &gt; 100</td><td>Clamped to 100 dp</td><td><code>MAX_BLUR_DP</code></td><td>✅</td></tr><tr><td>B5</td><td><code>cornerRadius</code> bigger than the view</td><td>Clamped to half the shortest side (pill/circle)</td><td><code>GlassShape.update</code>, outline</td><td>✅</td></tr><tr><td>B6</td><td><code>style.borderRadius</code> as a percentage</td><td>Ignored; theme default used</td><td><code>resolveCornerRadius</code></td><td>✅</td></tr><tr><td>B7</td><td><code>cornerRadius</code> + <code>style.borderRadius</code> both set</td><td>Prop wins</td><td><code>resolveCornerRadius</code></td><td>✅</td></tr><tr><td>B8</td><td><code>tint</code> is a <code>PlatformColor</code> / <code>DynamicColorIOS</code></td><td>Passed through untouched to native</td><td><code>resolveMaterial</code></td><td>✅</td></tr><tr><td>B9</td><td><code>tint</code> with its own alpha</td><td>Final alpha = colour alpha × <code>tintOpacity</code></td><td><code>SurfacePainter</code></td><td>✅</td></tr><tr><td>B10</td><td><code>lightAngle</code> outside ±180</td><td>Wrapped; animations take the shortest way</td><td><code>normalizeAngle</code>, <code>GlassConfig.lerpAngle</code></td><td>✅</td></tr><tr><td>B11</td><td><code>intensity</code> = 0</td><td>No blur/refraction/light; tint and border remain</td><td><code>resolveMaterial</code></td><td>✅</td></tr><tr><td>B12</td><td>Props change rapidly (every frame)</td><td>Transition restarts from mid-state; no jumps</td><td><code>GlassConfigTransition</code></td><td>✅</td></tr><tr><td>B13</td><td><code>backgroundColor</code> in glass style</td><td>Drawn <strong>under</strong> the glass (hidden by the blur). Use <code>tint</code> instead</td><td>docs</td><td>⚠️</td></tr><tr><td>B14</td><td>Style <code>borderWidth</code> on glass</td><td>RN draws its own border as well as the glass border</td><td>docs; use <code>borderWidth</code> prop</td><td>⚠️</td></tr></tbody></table><h2 id="c-layout-and-hierarchy-android" tabindex="-1">C. Layout and hierarchy (Android) <a class="header-anchor" href="#c-layout-and-hierarchy-android" aria-label="Permalink to &quot;C. Layout and hierarchy (Android)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Case</th><th>What happens</th><th>Where</th><th>Status</th></tr></thead><tbody><tr><td>C1</td><td>No <code>GlassBackdrop</code> on screen</td><td>Frosted solid (92% <code>fallbackColor</code>), logcat warning once</td><td><code>BackdropRegistry.resolve</code>, <code>SolidGlassRenderer</code></td><td>✅</td></tr><tr><td>C2</td><td>Glass <strong>inside</strong> its backdrop</td><td>Never binds to it (would loop); uses another backdrop or solid + warning</td><td><code>resolve</code> filter, invariant 6</td><td>✅</td></tr><tr><td>C3</td><td>Several backdrops</td><td>Largest on-screen overlap wins; <code>backdropId</code> to force one</td><td><code>bestOverlap</code></td><td>✅</td></tr><tr><td>C4</td><td><code>backdropId</code> doesn&#39;t exist</td><td>Solid + warning</td><td><code>resolve</code></td><td>✅</td></tr><tr><td>C5</td><td>Glass in a <code>Modal</code></td><td>Modal is its own window → needs its own backdrop inside the Modal</td><td>same-window filter; docs</td><td>✅</td></tr><tr><td>C6</td><td>Glass extends past its backdrop</td><td>The part of the glass outside the backdrop has nothing to show (tint only)</td><td>docs: use <code>absoluteFill</code> backdrops</td><td>⚠️</td></tr><tr><td>C6b</td><td>Glass flush with the screen / backdrop edge (tab bar, header)</td><td>Sampling clipped to the backdrop; blur clamps at the edge; no see-through fade</td><td><code>computeSampleRect</code>, <code>uOrigin</code></td><td>✅</td></tr><tr><td>C7</td><td>Backdrop has size 0</td><td>Solid; no redraw loop</td><td><code>RenderNodeGlassRenderer</code> guard</td><td>✅</td></tr><tr><td>C8</td><td>Glass size 0 or hidden (<code>display: none</code>, collapsed, animating from 0)</td><td>Nothing drawn, and no per-frame redraw loop</td><td><code>onPreDraw</code> guard (<code>width/height/isShown</code>)</td><td>✅</td></tr><tr><td>C9</td><td>Glass nested inside another glass</td><td>Inner glass samples the backdrop, not the outer glass</td><td>by design</td><td>✅</td></tr><tr><td>C10</td><td>Backdrop unmounts while glass is visible</td><td>Glass re-binds (another backdrop or solid)</td><td><code>removeBackdrop</code> → <code>requestRebind</code></td><td>✅</td></tr><tr><td>C11</td><td>Navigate away and back (backdrop re-attaches)</td><td>Recording re-enabled on rebind</td><td><code>ensureBinding</code> always refreshes flags</td><td>✅</td></tr><tr><td>C12</td><td>View recycling (Fabric)</td><td>Config, animations and renderer reset</td><td><code>prepareToRecycleView</code> → <code>resetForRecycle</code></td><td>✅</td></tr><tr><td>C13</td><td><code>removeClippedSubviews</code> detaches glass</td><td>Detach releases the renderer; re-attach rebinds</td><td>lifecycle</td><td>✅</td></tr><tr><td>C14</td><td>Backdrop has <code>opacity</code> &lt; 1</td><td>Glass copy uses the backdrop&#39;s own alpha</td><td><code>glassNode.setAlpha</code></td><td>✅</td></tr><tr><td>C15</td><td>A backdrop <strong>ancestor</strong> fades</td><td>Not reflected in the glass sample</td><td>—</td><td>⚠️</td></tr><tr><td>C16</td><td>Screen rotation / resize</td><td>New size → new shape, outline, capture</td><td><code>onSizeChanged</code>, <code>geometryChanged</code></td><td>✅</td></tr><tr><td>C17</td><td>RTL layouts</td><td>Geometry is matrix-based, direction-agnostic</td><td>—</td><td>✅</td></tr></tbody></table><h2 id="d-motion-and-content-changes-android" tabindex="-1">D. Motion and content changes (Android) <a class="header-anchor" href="#d-motion-and-content-changes-android" aria-label="Permalink to &quot;D. Motion and content changes (Android)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Case</th><th>What happens</th><th>Where</th><th>Status</th></tr></thead><tbody><tr><td>D1</td><td>List scrolls inside the backdrop</td><td>Same-frame update</td><td><code>onDescendantInvalidated</code> → notify</td><td>✅</td></tr><tr><td>D2</td><td>Glass moves (Animated native driver / Reanimated)</td><td>Matrix change detected in pre-draw</td><td><code>onPreDraw</code></td><td>✅</td></tr><tr><td>D3</td><td>Backdrop moves (parallax)</td><td>Same</td><td>same</td><td>✅</td></tr><tr><td>D4</td><td>Glass rotated / scaled (API 29+)</td><td>Exact alignment</td><td><code>transformMatrixToGlobal</code></td><td>✅</td></tr><tr><td>D5</td><td>Glass rotated / scaled (API 24–28)</td><td>Translation exact; rotation/scale ignored</td><td><code>ViewGeometry</code></td><td>⚠️</td></tr><tr><td>D6</td><td>Glass or backdrop scaled to 0</td><td>Matrix not invertible → skip glass for that frame</td><td><code>backdropToGlass</code> returns false</td><td>✅</td></tr><tr><td>D7</td><td>Video / camera / map in a <strong>TextureView</strong></td><td>Captured live on 12+; not on 7–11</td><td>RenderNode vs snapshot</td><td>⚠️</td></tr><tr><td>D8</td><td>Video / map in a <strong>SurfaceView</strong></td><td>Not capturable (separate surface): shows transparent</td><td>docs: use TextureView mode</td><td>⛔</td></tr><tr><td>D9</td><td>Throttled compat capture while scrolling</td><td>Trailing redraw guarantees the final frame</td><td><code>redrawAfterMs</code></td><td>✅</td></tr><tr><td>D11</td><td>Glass cards scrolling over a still background on Android 7–11</td><td>Snapshot shifted per frame; re-captured only past the padding: stays aligned</td><td><code>BackdropSnapshot.needsRecapture</code></td><td>✅</td></tr><tr><td>D13</td><td>Animation inside the backdrop far from any glass (spinner, Lottie)</td><td>Only glass overlapping the changed view redraws; others skip (counted in <code>skippedFarChanges</code>)</td><td><code>BackdropRegistry.notifyContentChanged</code> proximity filter</td><td>✅</td></tr><tr><td>D14</td><td>A view moves away from under a glass</td><td>Its previous rect is remembered, so the glass refreshes (no ghost)</td><td><code>lastTargetRects</code></td><td>✅</td></tr><tr><td>D12</td><td>Many glass views mounting at once (lists)</td><td>Battery-saver state cached (2 s, refreshed by broadcast) instead of an IPC per view</td><td><code>DeviceCapabilities</code></td><td>✅</td></tr><tr><td>D10</td><td>Animated GIF / Lottie inside backdrop</td><td>Treated like any invalidation (live)</td><td>D1</td><td>✅</td></tr></tbody></table><h2 id="e-device-and-os-android" tabindex="-1">E. Device and OS (Android) <a class="header-anchor" href="#e-device-and-os-android" aria-label="Permalink to &quot;E. Device and OS (Android)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Case</th><th>What happens</th><th>Where</th><th>Status</th></tr></thead><tbody><tr><td>E1</td><td>API 33+</td><td>SHADER tier</td><td><code>RendererTier</code></td><td>✅</td></tr><tr><td>E2</td><td>API 31–32</td><td>BLUR tier</td><td>same</td><td>✅</td></tr><tr><td>E3</td><td>API 24–30</td><td>COMPAT tier</td><td>same</td><td>✅</td></tr><tr><td>E4</td><td>AGSL fails to compile (driver bug)</td><td>Whole app → BLUR, one warning</td><td><code>GlassShader.createOrNull</code></td><td>✅</td></tr><tr><td>E5</td><td>Hardware acceleration disabled for the window</td><td>COMPAT_LIVE</td><td><code>RendererFactory</code></td><td>✅</td></tr><tr><td>E6</td><td>Software canvas (view-shot, <code>View.draw(bitmapCanvas)</code>)</td><td>One-off compat draw</td><td><code>RenderNodeGlassRenderer</code></td><td>✅</td></tr><tr><td>E7</td><td>HARDWARE bitmaps (Glide/Coil) on 7–11</td><td>Capture throws → solid, retry every 3 s, one warning</td><td><code>BackdropSnapshot</code></td><td>⚠️</td></tr><tr><td>E8</td><td>Out of memory creating a snapshot</td><td>Solid, one warning</td><td><code>BackdropSnapshot</code></td><td>✅</td></tr><tr><td>E9</td><td>Low-RAM / Android Go</td><td><code>auto</code> → LOW</td><td><code>QualityResolver</code></td><td>✅</td></tr><tr><td>E10</td><td>Battery saver toggled while running</td><td>Quality re-resolved live</td><td><code>SystemSettingsMonitor</code></td><td>✅</td></tr><tr><td>E11</td><td>Many glass views (&gt; 6, &gt; 12)</td><td><code>auto</code> steps down</td><td><code>QualityResolver</code></td><td>✅</td></tr><tr><td>E12</td><td>Emulator without GPU</td><td>Usually software GL: SHADER may be slow; use <code>quality=&quot;low&quot;</code> in debug</td><td>docs</td><td>⚠️</td></tr><tr><td>E13</td><td>Android 14+ receiver registration rules</td><td><code>RECEIVER_NOT_EXPORTED</code> flag used</td><td><code>SystemSettingsMonitor</code></td><td>✅</td></tr><tr><td>E14</td><td>OEM rejects receiver registration</td><td>Caught; glass works, battery saver just isn&#39;t live</td><td>same</td><td>✅</td></tr><tr><td>E15</td><td>No rotation sensor</td><td>Accelerometer fallback; none → tilt offset stays 0</td><td><code>MotionLightSource</code></td><td>✅</td></tr><tr><td>E16</td><td>App goes to background with <code>motionLighting</code></td><td>Sensor unregistered on pause, re-registered on resume</td><td><code>LiquidGlassModule</code> lifecycle</td><td>✅</td></tr></tbody></table><h2 id="f-touch-and-interaction" tabindex="-1">F. Touch and interaction <a class="header-anchor" href="#f-touch-and-interaction" aria-label="Permalink to &quot;F. Touch and interaction&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Case</th><th>What happens</th><th>Where</th><th>Status</th></tr></thead><tbody><tr><td>F1</td><td>Pressable / Button inside interactive glass</td><td>Touches pass through; glass only observes</td><td><code>dispatchTouchEvent</code></td><td>✅</td></tr><tr><td>F2</td><td>Glass inside a ScrollView, user starts scrolling</td><td>ScrollView intercepts → CANCEL → light fades, squish springs back</td><td><code>TouchLightController</code>, <code>PressAnimator</code></td><td>✅</td></tr><tr><td>F3</td><td><code>pointerEvents=&quot;none&quot;</code> on glass</td><td>No touch light</td><td><code>pointerEvents</code> check</td><td>✅</td></tr><tr><td>F4</td><td>Multi-touch</td><td>Follows the primary pointer</td><td><code>MotionEvent</code> x/y</td><td>✅</td></tr><tr><td>F5</td><td>User transform (scale) on glass + squish</td><td>No conflict (canvas squish)</td><td>ADR-005</td><td>✅</td></tr><tr><td>F6</td><td><code>interactive</code> turned off mid-press</td><td>Light and press state reset</td><td><code>commitConfig</code></td><td>✅</td></tr><tr><td>F7</td><td>Disabled <code>LiquidGlassButton</code></td><td>No native touch light / squish</td><td>Button passes <code>interactive={false}</code></td><td>✅</td></tr><tr><td>F8</td><td>iOS 26 button press</td><td>JS spring always runs; system glass reacts when the touch lands on the glass itself</td><td><code>nativeAnimatesPress</code> (Android only), effect view touchable when interactive</td><td>✅</td></tr></tbody></table><h2 id="g-accessibility" tabindex="-1">G. Accessibility <a class="header-anchor" href="#g-accessibility" aria-label="Permalink to &quot;G. Accessibility&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Case</th><th>What happens</th><th>Where</th><th>Status</th></tr></thead><tbody><tr><td>G1</td><td>iOS Reduce Transparency on</td><td>Opaque <code>fallbackColor</code>, live toggle</td><td><code>useReduceTransparency</code>, iOS notification</td><td>✅</td></tr><tr><td>G2</td><td>App-level &quot;reduce transparency&quot; (Android has no system setting)</td><td><code>reduceTransparency</code> prop</td><td>prop</td><td>✅</td></tr><tr><td>G3</td><td>Reduce motion / remove animations</td><td>No squish, no transitions, no tilt; highlight only</td><td><code>animationsOn</code>, <code>useReduceMotion</code></td><td>✅</td></tr><tr><td>G4</td><td>Text contrast on glass</td><td>Developer&#39;s responsibility; recipe provided</td><td>user guide 07</td><td>⚠️</td></tr><tr><td>G5</td><td>Screen readers</td><td>Glass is a normal View: all <code>accessibility*</code> props work; Button has <code>role=&quot;button&quot;</code> and disabled state</td><td><code>ReactViewManager</code></td><td>✅</td></tr></tbody></table><h2 id="h-ios-specifics" tabindex="-1">H. iOS specifics <a class="header-anchor" href="#h-ios-specifics" aria-label="Permalink to &quot;H. iOS specifics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Case</th><th>What happens</th><th>Where</th><th>Status</th></tr></thead><tbody><tr><td>H1</td><td>Android-only props on iOS</td><td>Ignored silently</td><td>04-ios.md</td><td>✅</td></tr><tr><td>H2</td><td>Glass layers vs React children order</td><td>Children always above glass (separate container)</td><td><code>mountChildComponentView</code></td><td>✅</td></tr><tr><td>H3</td><td>Touch on empty area of glass</td><td>Hits the glass component (container returns nil)</td><td><code>LGChildContainerView</code></td><td>✅</td></tr><tr><td>H4</td><td>Dark mode switch</td><td>System materials adapt; JS re-resolves tint/fallback per scheme</td><td><code>useGlassTheme</code></td><td>✅</td></tr><tr><td>H5</td><td>Animating <code>opacity</code> on glass (or a parent) on iOS</td><td>UIKit renders blur incorrectly while alpha &lt; 1 (Apple limitation)</td><td>docs: animate content, not the glass</td><td>⚠️</td></tr></tbody></table>',18)])])}const g=d(r,[["render",s]]);export{u as __pageData,g as default};
